85	// openError turns a refused socket option (ENOPROTOOPT, EOPNOTSUPP) into
86	// ErrUnsupported, keeping the raw error for the message. Anything else is
87	// returned as is: a refused connect() is not "unsupported", and the system
88	// prober wraps its own socket and setsockopt permission errors itself.
89	func openError(err error) error {
90		for _, errno := range []error{syscall.ENOPROTOOPT, syscall.EOPNOTSUPP} {
91			if errors.Is(err, errno) {
92				return fmt.Errorf("%w: %w", ErrUnsupported, err)
93			}
94		}
95		return err
96	}
