98	// probeAll runs phase 2: one goroutine per connection.
99	func probeAll(ctx context.Context, target netip.Addr, opts Options, conns []probeConn, start time.Time) Result {
100		n := len(conns)
101		results := make(chan probeResult, n)
102		cancels := make([]context.CancelFunc, n+1) // indexed by TTL
103		var wg sync.WaitGroup
104		for i, c := range conns {
105			ttl := i + 1
106			var tctx context.Context
107			tctx, cancels[ttl] = context.WithCancel(ctx)
108			wg.Add(1)
109			go func() {
110				defer wg.Done()
111				defer func() { _ = c.close() }()
112				results <- probeOne(tctx, c, ttl, target, opts.ProbeTimeout)
113			}()
114		}
115	
116		t := newTally(n)
117		cutAbove := func() {
118			if term := t.terminal(); term > 0 {
119				for ttl := term + 1; ttl <= n; ttl++ {
120					cancels[ttl]()
121				}
122			}
123		}
124	collect:
125		for !t.complete() {
126			select {
127			case r := <-results:
128				t.add(r)
129				cutAbove()
130			case <-ctx.Done():
131				break collect
132			}
133		}
134		for _, cancel := range cancels[1:] {
135			cancel()
136		}
137		wg.Wait()
138		close(results)
139		for r := range results { // answers that landed while stopping
140			t.add(r)
141		}
142	
143		if t.complete() {
144			return t.result(target, start)
145		}
146		return endedEarly(ctx, target, t, n, start)
147	}
