149	// probeOne sends the probe for one TTL and turns what comes back into a Hop.
150	func probeOne(ctx context.Context, c probeConn, ttl int, target netip.Addr, timeout time.Duration) probeResult {
151		sentAt, err := c.send()
152		if err != nil {
153			if ctx.Err() != nil {
154				return probeResult{ttl: ttl}
155			}
156			return probeResult{ttl: ttl, hop: Hop{TTL: ttl, Kind: HopError, Err: err}, resolved: true}
157		}
158		rep, err := c.await(ctx, sentAt.Add(timeout))
159		recvAt := time.Now()
160		switch {
161		case err != nil && ctx.Err() != nil:
162			return probeResult{ttl: ttl}
