func TestRunCancelMidTraceStreamsOnlyResolvedHops(t *testing.T) {
	fp := newFake(5, table(probeSpec{ignoreUntil: true}, map[int]probeSpec{
		1: {rep: routerReply("10.0.0.1"), delay: 5 * time.Millisecond},
