1	package nettrace
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"net/netip"
8		"sync"
9		"syscall"
10		"time"
11	)
12	
13	// prober opens one probe connection per TTL. The system implementation lives
14	// in the platform files; the tests drive run with a fake.
15	type prober interface {
16		// open returns a connection whose probes leave with the given TTL.
17		open(ctx context.Context, dst netip.Addr, ttl int) (probeConn, error)
18	}
19	
20	// probeConn sends one probe and waits for what answers it.
21	type probeConn interface {
22		// send emits the probe and returns the time it left.
23		send() (time.Time, error)
24		// await waits for the answer until the given time. It returns errSilent
25		// when nothing came back by then, and ctx.Err() when ctx ended first.
26		await(ctx context.Context, until time.Time) (reply, error)
27		close() error
28	}
29	
30	// errSilent is await's answer when nothing came back before its deadline.
31	var errSilent = errors.New("no answer before the probe timeout")
32	
33	// probeResult is what one TTL's goroutine hands back. resolved is false when
34	// the probe was cut short (cancellation, deadline, upper TTL no longer needed).
35	type probeResult struct {
36		ttl      int
37		hop      Hop
38		resolved bool
39	}
40	
41	// run traces the path with p. Every connection is opened first, in the
42	// caller's goroutine, so that a failing open stops everything before any
43	// probe is sent; then one goroutine per TTL sends and awaits in parallel.
44	func run(ctx context.Context, target netip.Addr, opts Options, p prober) (Result, error) {
45		opts = opts.Normalized()
46		start := time.Now()
47		runCtx, cancel := context.WithTimeout(ctx, opts.Deadline)
48		defer cancel()
49	
50		conns, err := openAll(runCtx, p, target, opts.MaxHops)
51		if err != nil {
52			if runCtx.Err() != nil {
53				return endedEarly(runCtx, target, nil, opts.MaxHops, start), nil
54			}
55			return Result{}, openError(err)
56		}
57		return probeAll(runCtx, target, opts, conns, start), nil
58	}
59	
60	// openAll opens one connection per TTL, 1 to n. On failure it closes the ones
61	// already open and returns the error.
62	func openAll(ctx context.Context, p prober, target netip.Addr, n int) ([]probeConn, error) {
63		conns := make([]probeConn, 0, n)
64		for ttl := 1; ttl <= n; ttl++ {
65			if err := ctx.Err(); err != nil {
66				closeAll(conns)
67				return nil, err
68			}
69			c, err := p.open(ctx, target, ttl)
70			if err != nil {
71				closeAll(conns)
72				return nil, err
73			}
74			conns = append(conns, c)
75		}
76		return conns, nil
77	}
78	
79	func closeAll(conns []probeConn) {
80		for _, c := range conns {
81			_ = c.close()
82		}
83	}
84	
85	// openError turns a refused socket option (ENOPROTOOPT, EOPNOTSUPP) into
86	// ErrUnsupported, keeping the raw error for the message. Anything else is
87	// returned as is: a refused connect() is not "unsupported", and the system
88	// prober wraps its own socket and setsockopt permission errors itself.
89	func openError(err error) error {
90		for _, errno := range []error{syscall.ENOPROTOOPT, syscall.EOPNOTSUPP} {
91			if errors.Is(err, errno) {
92				return fmt.Errorf("%w: %w", ErrUnsupported, err)
93			}
94		}
95		return err
96	}
97	
98	// probeAll runs phase 2: one goroutine per connection.
99	func probeAll(ctx context.Context, target netip.Addr, opts Options, conns []probeConn, start time.Time) Result {
100		n := len(conns)
101		results := make(chan probeResult, n)
102		cancels := make([]context.CancelFunc, n+1) // indexed by TTL
103		var wg sync.WaitGroup
104		for i, c := range conns {
105			ttl := i + 1
106			var tctx context.Context
107			tctx, cancels[ttl] = context.WithCancel(ctx)
108			wg.Add(1)
109			go func() {
110				defer wg.Done()
111				defer func() { _ = c.close() }()
112				results <- probeOne(tctx, c, ttl, target, opts.ProbeTimeout)
113			}()
114		}
115	
116		t := newTally(n)
117		cutAbove := func() {
118			if term := t.terminal(); term > 0 {
119				for ttl := term + 1; ttl <= n; ttl++ {
120					cancels[ttl]()
121				}
122			}
123		}
124	collect:
125		for !t.complete() {
126			select {
127			case r := <-results:
128				t.add(r)
129				cutAbove()
130			case <-ctx.Done():
131				break collect
132			}
133		}
134		for _, cancel := range cancels[1:] {
135			cancel()
136		}
137		wg.Wait()
138		close(results)
139		for r := range results { // answers that landed while stopping
140			t.add(r)
141		}
142	
143		if t.complete() {
144			return t.result(target, start)
145		}
146		return endedEarly(ctx, target, t, n, start)
147	}
148	
149	// probeOne sends the probe for one TTL and turns what comes back into a Hop.
150	func probeOne(ctx context.Context, c probeConn, ttl int, target netip.Addr, timeout time.Duration) probeResult {
151		sentAt, err := c.send()
152		if err != nil {
153			if ctx.Err() != nil {
154				return probeResult{ttl: ttl}
155			}
156			return probeResult{ttl: ttl, hop: Hop{TTL: ttl, Kind: HopError, Err: err}, resolved: true}
157		}
158		rep, err := c.await(ctx, sentAt.Add(timeout))
159		recvAt := time.Now()
160		switch {
161		case err != nil && ctx.Err() != nil:
162			return probeResult{ttl: ttl}
163		case errors.Is(err, errSilent):
164			return probeResult{ttl: ttl, hop: Hop{TTL: ttl, Kind: HopSilent}, resolved: true}
165		case err != nil:
166			return probeResult{ttl: ttl, hop: Hop{TTL: ttl, Kind: HopError, Err: err}, resolved: true}
167		}
168		rtt := rep.RTT
169		if rtt == 0 {
170			rtt = recvAt.Sub(sentAt)
171		}
172		hop := Hop{TTL: ttl, Kind: classify(rep, target), Addr: rep.Addr, RTT: rtt, ICMPType: rep.ICMPType, ICMPCode: rep.ICMPCode}
173		return probeResult{ttl: ttl, hop: hop, resolved: true}
174	}
175	
176	// tally collects the resolved hops of a run.
177	type tally struct {
178		hops []probeResult // indexed by TTL, index 0 unused
179	}
180	
181	func newTally(n int) *tally { return &tally{hops: make([]probeResult, n+1)} }
182	
183	func (t *tally) add(r probeResult) {
184		if r.resolved {
185			t.hops[r.ttl] = r
186		}
187	}
188	
189	// terminal returns the smallest TTL that reached or was refused, or 0.
190	func (t *tally) terminal() int {
191		for ttl := 1; ttl < len(t.hops); ttl++ {
192			if r := t.hops[ttl]; r.resolved && (r.hop.Kind == HopTarget || r.hop.Kind == HopUnreachable) {
193				return ttl
194			}
195		}
196		return 0
197	}
198	
199	// complete reports whether the trace can end: every TTL up to the terminal
200	// one (or every TTL when there is none) is resolved.
201	func (t *tally) complete() bool {
202		limit := len(t.hops) - 1
203		if term := t.terminal(); term > 0 {
204			limit = term
205		}
206		for ttl := 1; ttl <= limit; ttl++ {
207			if !t.hops[ttl].resolved {
208				return false
209			}
210		}
211		return true
212	}
213	
214	// result builds the Result of a complete tally.
215	func (t *tally) result(target netip.Addr, start time.Time) Result {
216		last, outcome := len(t.hops)-1, OutcomeMaxHops
217		if term := t.terminal(); term > 0 {
218			last = term
219			outcome = OutcomeReached
220			if t.hops[term].hop.Kind == HopUnreachable {
221				outcome = OutcomeUnreachable
222			}
223		}
224		hops := make([]Hop, 0, last)
225		for ttl := 1; ttl <= last; ttl++ {
226			hops = append(hops, t.hops[ttl].hop)
227		}
228		return Result{Target: target, Outcome: outcome, Hops: hops, Duration: time.Since(start)}
229	}
230	
231	// endedEarly builds the Result of a run that ctx cut short: one entry per TTL
232	// (n entries, index TTL-1), the resolved hops as they are and every other one
233	// as HopUnresolved with its TTL. t is nil when nothing was probed yet.
234	func endedEarly(ctx context.Context, target netip.Addr, t *tally, n int, start time.Time) Result {
235		res := Result{Target: target, Outcome: OutcomeCancelled, Hops: make([]Hop, 0, n), Duration: time.Since(start)}
236		if errors.Is(ctx.Err(), context.DeadlineExceeded) {
237			res.Outcome = OutcomeDeadline
238		}
239		for ttl := 1; ttl <= n; ttl++ {
240			if t != nil && t.hops[ttl].resolved {
241				res.Hops = append(res.Hops, t.hops[ttl].hop)
242			} else {
243				res.Hops = append(res.Hops, Hop{TTL: ttl, Kind: HopUnresolved})
244			}
245		}
246		return res
247	}
248

160		Duration time.Duration
161	}
162	
163	// Supported reports whether this platform can trace: nil, or ErrUnsupported.
164	func Supported() error {
165		return supported()
166	}
167	
168	// Trace probes the path to target. An IPv4-mapped IPv6 target is converted to
169	// IPv4; any other non-IPv4 target gets ErrNotIPv4 and nothing is sent. An
170	// unspecified (0.0.0.0), multicast or limited broadcast (255.255.255.255)
171	// target gets ErrNotUnicast. Subnet broadcasts cannot be told apart and are not
172	// checked. Loopback and private addresses are allowed: whether tracing them is
173	// acceptable is the caller's decision, at its own boundary.
174	//
175	// The errors Trace returns and Hop.Err carry raw platform text (errno
176	// messages): match the sentinels with errors.Is and show fixed labels, never
177	// that text in a summary.
178	func Trace(ctx context.Context, target netip.Addr, opts Options) (Result, error) {
179		if err := supported(); err != nil {
180			return Result{}, err
181		}
182		target = target.Unmap()
183		if !target.Is4() {
184			return Result{}, ErrNotIPv4
185		}
186		if target.IsUnspecified() || target.IsMulticast() || target == netip.AddrFrom4([4]byte{255, 255, 255, 255}) {
187			return Result{}, ErrNotUnicast
188		}
189		return run(ctx, target, opts, systemProber())
190	}
