1	package nettrace
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"net/netip"
8		"sort"
9		"sync/atomic"
10		"syscall"
11		"testing"
12		"time"
13	)
14	
15	// TraceEach streams each resolved hop to a callback. These tests drive the
16	// engine (run) with the fake prober of engine_test.go, so they run on every
17	// platform; the public TraceEach is only checked where no socket is needed.
18	
19	// hopRecorder is a callback that keeps what it is given in a plain slice, with
20	// no lock: the contract is that calls are sequential, so -race must stay clean.
21	// It also counts overlapping calls and calls made after the run returned.
22	type hopRecorder struct {
23		hops    []Hop
24		inCall  atomic.Int32
25		over    atomic.Bool
26		after   atomic.Int32
27		overlap atomic.Int32
28		// nap widens the window in which an overlapping call would be seen.
29		nap time.Duration
30		// also runs inside the callback, after recording (n = calls so far).
31		also func(h Hop, n int)
32	}
33	
34	func (r *hopRecorder) onHop(h Hop) {
35		if r.over.Load() {
36			r.after.Add(1)
37		}
38		if r.inCall.Add(1) != 1 {
39			r.overlap.Add(1)
40		}
41		r.hops = append(r.hops, h)
42		if r.nap > 0 {
43			time.Sleep(r.nap)
44		}
45		if r.also != nil {
46			r.also(h, len(r.hops))
47		}
48		r.inCall.Add(-1)
49	}
50	
51	// finish marks the run as returned. Call it right after run returns.
52	func (r *hopRecorder) finish() { r.over.Store(true) }
53	
54	func (r *hopRecorder) check(t *testing.T) {
55		t.Helper()
56		if n := r.after.Load(); n != 0 {
57			t.Errorf("%d callback calls after the run returned", n)
58		}
59		if n := r.overlap.Load(); n != 0 {
60			t.Errorf("%d callback calls overlapped another one", n)
61		}
62		for _, h := range r.hops {
63			if h.Kind == HopUnresolved {
64				t.Errorf("callback got an unresolved hop: %+v", h)
65			}
66		}
67	}
68	
69	func (r *hopRecorder) ttls() []int {
70		out := make([]int, 0, len(r.hops))
71		for _, h := range r.hops {
72			out = append(out, h.TTL)
73		}
74		sort.Ints(out)
75		return out
76	}
77	
78	func sameInts(a, b []int) bool {
79		if len(a) != len(b) {
80			return false
81		}
82		for i := range a {
83			if a[i] != b[i] {
84				return false
85			}
86		}
87		return true
88	}
89	
90	// sameHop compares what a hop says, not its measured RTT.
91	func sameHop(a, b Hop) bool {
92		return a.TTL == b.TTL && a.Kind == b.Kind && a.Addr == b.Addr &&
93			a.ICMPType == b.ICMPType && a.ICMPCode == b.ICMPCode && errors.Is(a.Err, b.Err)
94	}
95	
96	func sameHops(a, b []Hop) bool {
97		if len(a) != len(b) {
98			return false
99		}
100		for i := range a {
101			if !sameHop(a[i], b[i]) {
102				return false
103			}
104		}
105		return true
106	}
107	
108	func TestRunStreamsEachResolvedHopOnce(t *testing.T) {
109		// TTL 2 is silent (a resolved hop), TTL 5 never answers and is cut.
110		newProber := func() *fakeProber {
111			return newFake(5, table(probeSpec{ignoreUntil: true}, map[int]probeSpec{
112				1: {rep: routerReply("10.0.0.1"), delay: 5 * time.Millisecond},
113				2: {}, // silent until the probe timeout
114				3: {rep: routerReply("10.0.0.3"), delay: 10 * time.Millisecond},
115				4: {rep: targetReply(), delay: 15 * time.Millisecond},
116			}))
117		}
118		opts := Options{MaxHops: 5, ProbeTimeout: 150 * time.Millisecond}
119	
120		rec := &hopRecorder{nap: 5 * time.Millisecond}
121		fp := newProber()
122		res, err := run(context.Background(), engineTarget, opts, fp, rec.onHop)
123		rec.finish()
124		if err != nil {
125			t.Fatalf("run: %v", err)
126		}
127		rec.check(t)
128		if got, want := rec.ttls(), []int{1, 2, 3, 4}; !sameInts(got, want) {
129			t.Errorf("callback TTLs = %v, want %v (each resolved hop once, none above the target)", got, want)
130		}
131		for _, h := range rec.hops {
132			if h.TTL == 2 && h.Kind != HopSilent {
133				t.Errorf("TTL 2 Kind = %v, want silent", h.Kind)
134			}
135		}
136		assertBalanced(t, fp)
137	
138		// The Result is the same with and without a callback.
139		plain, err := run(context.Background(), engineTarget, opts, newProber(), nil)
140		if err != nil {
141			t.Fatalf("run with nil callback: %v", err)
142		}
143		if plain.Outcome != res.Outcome || !sameHops(plain.Hops, res.Hops) {
144			t.Errorf("Result differs with a callback:\n with: %v %+v\n nil:  %v %+v", res.Outcome, res.Hops, plain.Outcome, plain.Hops)
145		}
146		// And here what the callback saw is exactly the Result's hops.
147		byTTL := append([]Hop(nil), rec.hops...)
148		sort.Slice(byTTL, func(i, j int) bool { return byTTL[i].TTL < byTTL[j].TTL })
149		if !sameHops(byTTL, res.Hops) {
150			t.Errorf("callback hops %+v differ from Result.Hops %+v", byTTL, res.Hops)
151		}
152	}
153	
154	// A nil callback gives the same result whatever the scenario.
155	func TestRunNilCallbackMatchesCallback(t *testing.T) {
156		silentForever := probeSpec{ignoreUntil: true}
157		tests := []struct {
158			name string
159			n    int
160			spec func(int) probeSpec
161			want Outcome
162		}{
163			{"reaches the target", 6, table(silentForever, map[int]probeSpec{
164				1: {rep: routerReply("10.0.0.1")}, 2: {rep: routerReply("10.0.0.2"), delay: 5 * time.Millisecond},
165				3: {rep: targetReply(), delay: 10 * time.Millisecond},
166			}), OutcomeReached},
167			{"all silent ends at max hops", 3, table(probeSpec{}, nil), OutcomeMaxHops},
168			{"router reports unreachable", 4, table(silentForever, map[int]probeSpec{
169				1: {rep: routerReply("10.0.0.1")}, 2: {rep: unreachReply("10.0.0.2", 1), delay: 5 * time.Millisecond},
170			}), OutcomeUnreachable},
171			{"probe errors become error hops", 3, table(probeSpec{}, map[int]probeSpec{
172				1: {sendErr: syscall.EPERM},
173			}), OutcomeMaxHops},
174		}
175		for _, tc := range tests {
176			t.Run(tc.name, func(t *testing.T) {
177				opts := Options{MaxHops: tc.n, ProbeTimeout: 100 * time.Millisecond}
178				rec := &hopRecorder{}
179				with, err := run(context.Background(), engineTarget, opts, newFake(tc.n, tc.spec), rec.onHop)
180				rec.finish()
181				if err != nil {
182					t.Fatalf("run with callback: %v", err)
183				}
184				without, err := run(context.Background(), engineTarget, opts, newFake(tc.n, tc.spec), nil)
185				if err != nil {
